from itertools import combinations
from collections import Counter


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start = data["source"]
    initial_mask = bits.get(start, 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    coupons = data["coupons"]
    initial = (start, initial_mask, 0)
    best = {initial: data["start"]}
    queue = [(data["start"], start, initial_mask, 0)]
    while queue:
        time, node, mask, spent = heapq.heappop(queue)
        state = (node, mask, spent)
        if best.get(state) != time:
            continue
        if (node == data["target"] and mask == full and
                (coupon_rule == "at_most" or spent == coupons)):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], spent)]
            if spent < coupons:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, spent + 1))
            for duration, next_spent in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_spent)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_spent))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    best_vector = None
    best_install = None

    def closure(assigned):
        ranges = {}
        graph = {}
        queue = []
        for name, bounds in roots.items():
            ranges.setdefault(name, []).append(tuple(bounds))
            queue.append(name)
        seen_edges = set()
        while queue:
            name = queue.pop()
            if name not in assigned:
                continue
            row = assigned[name]
            ver = row["version"]
            if any(not low <= ver <= high for low, high in ranges[name]):
                return None
            graph.setdefault(name, [])
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                edge = (name, other, dep["min"], dep["max"])
                if edge in seen_edges:
                    continue
                seen_edges.add(edge)
                graph[name].append(other)
                ranges.setdefault(other, []).append((dep["min"], dep["max"]))
                queue.append(other)
        for name, row in assigned.items():
            if name not in ranges:
                continue
            ver = row["version"]
            if any(not low <= ver <= high for low, high in ranges[name]):
                return None
        unresolved = [name for name in ranges if name not in assigned]
        return ranges, graph, unresolved

    def visit(assigned):
        nonlocal best_vector, best_install
        result = closure(assigned)
        if result is None:
            return
        ranges, graph, unresolved = result
        if unresolved:
            name = min(unresolved)
            low = max(bound[0] for bound in ranges[name])
            high = min(bound[1] for bound in ranges[name])
            if name in pins:
                low = max(low, pins[name])
                high = min(high, pins[name])
            forbidden = set(blocked.get(name, []))
            for row in packages[name]:
                version = row["version"]
                if low <= version <= high and version not in forbidden:
                    nxt = dict(assigned)
                    nxt[name] = row
                    visit(nxt)
            return

        # All reachable packages are assigned. Reject dependency cycles.
        color = {}
        def acyclic(node):
            if color.get(node) == 1:
                return False
            if color.get(node) == 2:
                return True
            color[node] = 1
            if any(not acyclic(child) for child in graph.get(node, [])):
                return False
            color[node] = 2
            return True
        if not all(acyclic(node) for node in graph):
            return
        installed = {name: assigned[name]["version"] for name in ranges}
        vector = tuple(installed.get(name, -1) for name in names)
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_install = installed

    visit({})
    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None
    for subset in combinations(options, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in subset)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(job["value"] for job in subset)
        selected = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


